/* prog30_escape_unescape.c
 *
 * Reimplementation of the original binary's observable behaviour.
 *
 *   prog30_escape_unescape escape   <string>   – escape special characters
 *   prog30_escape_unescape unescape <string>   – un‑escape them
 *
 * Errors:
 *   USAGE          – not enough arguments
 *   INVALID        – input longer than 1023 characters
 *   INVALID_MODE   – unknown mode
 *
 * The program prints the result (or the error message) followed by a
 * newline (via puts).
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1023          /* limit enforced by the original binary */
#define OUT_BUF   4096          /* more than enough for escaped output */

/* Escape the characters \\, \", newline and tab. */
static void escape_string(const char *src, char *dst)
{
    while (*src) {
        switch (*src) {
            case '\\':
                *dst++ = '\\';
                *dst++ = '\\';
                break;
            case '"':
                *dst++ = '\\';
                *dst++ = '"';
                break;
            case '\n':
                *dst++ = '\\';
                *dst++ = 'n';
                break;
            case '\t':
                *dst++ = '\\';
                *dst++ = 't';
                break;
            default:
                *dst++ = *src;
                break;
        }
        ++src;
    }
    *dst = '\0';
}

/* Un‑escape the same four escape sequences.  Unknown sequences are left
   unchanged (the original program behaved this way). */
static void unescape_string(const char *src, char *dst)
{
    while (*src) {
        if (*src == '\\' && src[1] != '\0') {
            char nxt = src[1];
            switch (nxt) {
                case '\\':
                    *dst++ = '\\';
                    break;
                case '"':
                    *dst++ = '"';
                    break;
                case 'n':
                    *dst++ = '\n';
                    break;
                case 't':
                    *dst++ = '\t';
                    break;
                default:
                    /* keep the backslash and the following character */
                    *dst++ = '\\';
                    *dst++ = nxt;
                    break;
            }
            src += 2;               /* skip the escape sequence */
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }

    char out[OUT_BUF];

    if (strcmp(mode, "escape") == 0) {
        escape_string(input, out);
        puts(out);
    } else if (strcmp(mode, "unescape") == 0) {
        unescape_string(input, out);
        puts(out);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
